const data = $input.first().json;
const timestamp = new Date().toISOString();
const courierCount = data.total_active_couriers || 0;

console.log(`[${timestamp}] Weather check: ${courierCount} active couriers`);

if (courierCount === 0) {
  console.log('No active couriers, skipping weather checks');
  return [];
}

// Extract couriers array
return data.couriers.map(courier => ({
  json: courier
}));

const data = $input.first().json;
const timestamp = new Date().toISOString();
const courierId = data.courier_id;

// Check if we recently sent an alert to this courier (throttling)
const recentAlerts = $workflow.staticData.recentAlerts || {};
const lastAlertTime = recentAlerts[courierId];
const throttleDurationMs = 60 * 60 * 1000; // 1 hour

if (lastAlertTime && (Date.now() - lastAlertTime < throttleDurationMs)) {
  console.log(`[${timestamp}] Alert throttled for courier #${courierId} (last alert: ${new Date(lastAlertTime).toISOString()})`);
  return [];
}

// Update last alert time
recentAlerts[courierId] = Date.now();
$workflow.staticData.recentAlerts = recentAlerts;

// Get courier info from previous node
const previousData = $('Split Couriers').first().json;

const severityEmoji = {
  'critical': '🚨',
  'high': '⚠️',
  'moderate': '⚡',
  'low': '💡',
  'none': '✅'
};

const emoji = severityEmoji[data.severity] || '⚠️';

console.log(`[${timestamp}] Sending ${data.severity} weather alert to courier #${courierId}`);

return {
  json: {
    courier_id: courierId,
    courier_name: previousData.courier_name,
    phone: previousData.phone,
    severity: data.severity,
    severity_emoji: emoji,
    condition: data.condition,
    description: data.description,
    recommendation: data.recommendation,
    impact_score: data.impact_score,
    warnings: data.warnings || [],
    location: data.location,
    temperature: data.weather_conditions?.temperature,
    wind_speed: data.weather_conditions?.wind_speed,
    visibility: data.weather_conditions?.visibility,
    timestamp
  }
};

