const data = $input.first().json;
const timestamp = new Date().toISOString();

// Build SMS message
const message = `${data.severity_emoji} LOOP Weather Alert\n\nCourier: ${data.courier_name}\nLocation: ${data.location}\nCondition: ${data.description}\n\n${data.recommendation}\n\n${data.warnings.join('\n') || 'No additional warnings'}\n\nStay safe!`;

console.log(`[${timestamp}] SMS Alert prepared for ${data.phone}`);

return {
  json: {
    phone: data.phone,
    message,
    courier_id: data.courier_id,
    severity: data.severity
  }
};

// In production, integrate with Twilio or similar SMS service
const data = $input.first().json;
const timestamp = new Date().toISOString();

console.log(`[${timestamp}] SMS Alert sent (simulated) to ${data.phone}`);
console.log(`Message: ${data.message}`);

// PRODUCTION CODE (uncomment when ready):
