// return await $http.post(twilioUrl, {
//   To: data.phone,
//   From: process.env.TWILIO_PHONE,
//   Body: data.message
// });

return {
  json: {
    success: true,
    phone: data.phone,
    severity: data.severity,
    sent_at: timestamp
  }
};

// Check if many alerts were triggered (potential system-wide issue)
const allAlerts = $workflow.staticData.alertCounts || {};
const currentHour = new Date().getHours();

if (!allAlerts[currentHour]) {
  allAlerts[currentHour] = 0;
}

allAlerts[currentHour]++;
$workflow.staticData.alertCounts = allAlerts;

const threshold = 5; // Alert admin if more than 5 couriers affected

if (allAlerts[currentHour] >= threshold) {
  console.log(`ADMIN ALERT: ${allAlerts[currentHour]} weather alerts sent this hour`);

  return {
    json: {
      alert_admin: true,
      alert_count: allAlerts[currentHour],
      hour: currentHour,
      message: `Multiple weather alerts triggered (${allAlerts[currentHour]} this hour). System-wide weather issue possible.`
    }
  };
}

return [];

const data = $input.first().json;
const timestamp = new Date().toISOString();

console.log(`[${timestamp}] No alert needed - good weather conditions`);

return {
  json: {
    skipped: true,
    reason: 'Weather conditions acceptable',
    timestamp
  }
};

const error = $input.first().json;
const timestamp = new Date().toISOString();

console.error(`[${timestamp}] Weather check error:`, error.message || error);

return {
  json: {
    error: true,
    message: error.message || 'API request failed',
    timestamp
  }
};
